{"file_text": "@using sv_f1a8f87ae7e742d4b3071cf5a81b094d.Models

@* Expandable panel for changing the user's password *@

<div class="change-password-panel">
    <button class="btn btn-outline-secondary w-100 text-start" @onclick="TogglePanel">
        <span class="me-2">@(_expanded ? "▾" : "▸")</span>
        Change Password
    </button>

    @if (_expanded)
    {
        <div class="password-fields mt-3">
            <div class="mb-3">
                <label class="form-label">Current Password</label>
                <input type="password" class="form-control" @bind="_currentPassword" />
            </div>

            <div class="mb-3">
                <label class="form-label">New Password</label>
                <input type="password" class="form-control" @bind="_newPassword" />
            </div>

            <div class="mb-3">
                <label class="form-label">Confirm New Password</label>
                <input type="password" class="form-control" @bind="_confirmPassword" />
            </div>

            @if (_validationError is not null)
            {
                <div class="alert alert-warning" role="alert">@_validationError</div>
            }

            @if (_successMessage is not null)
            {
                <div class="alert alert-success" role="alert">@_successMessage</div>
            }

            @if (_errorMessage is not null)
            {
                <div class="alert alert-danger" role="alert">@_errorMessage</div>
            }

            <button class="btn btn-primary" @onclick="UpdatePassword" disabled="@_saving">
                @(_saving ? "Updating..." : "Update Password")
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    private bool _expanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _validationError;
    private string? _successMessage;
    private string? _errorMessage;
    private bool _saving;

    private void TogglePanel() => _expanded = !_expanded;

    private async Task UpdatePassword()
    {
        _validationError = null;
        _successMessage = null;
        _errorMessage = null;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _validationError = "Current password is required.";
            return;
        }

        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _validationError = "New password is required.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _validationError = "New password and confirmation do not match.";
            return;
        }

        _saving = true;
        try
        {
            await OnChangePassword.InvokeAsync((_currentPassword, _newPassword));
            _successMessage = "Password updated successfully!";
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _errorMessage = $"Failed to update password: {ex.Message}";
        }
        finally
        {
            _saving = false;
        }
    }
}
