@using sv_f1a8f87ae7e742d4b3071cf5a81b094d.Models
@using sv_f1a8f87ae7e742d4b3071cf5a81b094d.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h3>Notifications</h3>

    @if (_loading)
    {
        <p>Loading notification preferences...</p>
    }
    else
    {
        <div class="notification-form">
            <div class="toggle-group">
                <div class="toggle-item">
                    <label class="form-check form-switch">
                        <input type="checkbox" class="form-check-input" @bind="_emailNotifications" />
                        <span class="form-check-label">Email Notifications</span>
                    </label>
                </div>

                <div class="toggle-item">
                    <label class="form-check form-switch">
                        <input type="checkbox" class="form-check-input" @bind="_pushNotifications" />
                        <span class="form-check-label">Push Notifications</span>
                    </label>
                </div>

                <div class="toggle-item">
                    <label class="form-check form-switch">
                        <input type="checkbox" class="form-check-input" @bind="_weeklyDigest" />
                        <span class="form-check-label">Weekly Digest</span>
                    </label>
                </div>
            </div>

            <hr />

            <h5>Muted Channels</h5>
            @if (_allChannels.Count == 0)
            {
                <p class="text-muted">No channels available.</p>
            }
            else
            {
                <div class="channel-list">
                    @foreach (var channel in _allChannels)
                    {
                        <div class="form-check">
                            <input type="checkbox" class="form-check-input"
                                   id="@($"ch-{channel}")"
                                   checked="@_mutedChannels.Contains(channel)"
                                   @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                            <label class="form-check-label" for="@($"ch-{channel}")">@channel</label>
                        </div>
                    }
                </div>
            }

            <div class="form-actions mt-3">
                <button class="btn btn-primary" @onclick="SavePreferences" disabled="@_saving">
                    @(_saving ? "Saving..." : "Save Preferences")
                </button>
            </div>

            @if (_showSuccess)
            {
                <div class="alert alert-success mt-3" role="alert">
                    Notification preferences saved!
                </div>
            }

            @if (_errorMessage is not null)
            {
                <div class="alert alert-danger mt-3" role="alert">
                    @_errorMessage
                </div>
            }
        </div>
    }
</div>

@code {
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private List<string> _allChannels = new();
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;
    private string? _errorMessage;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        try
        {
            var prefs = await SettingsService.GetNotificationPrefsAsync();
            _emailNotifications = prefs.EmailNotifications;
            _pushNotifications = prefs.PushNotifications;
            _weeklyDigest = prefs.WeeklyDigest;
            _allChannels = prefs.MutedChannels.Count > 0
                ? new List<string>(prefs.MutedChannels)
                : new List<string> { "General", "Announcements", "Engineering", "Design", "Marketing" };
            _mutedChannels = new HashSet<string>(prefs.MutedChannels);
        }
        finally
        {
            _loading = false;
        }
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        _saving = true;
        _showSuccess = false;
        _errorMessage = null;

        try
        {
            var prefs = new NotificationPrefs(
                _emailNotifications,
                _pushNotifications,
                _weeklyDigest,
                _mutedChannels.ToList());
            await SettingsService.SaveNotificationPrefsAsync(prefs);
            _showSuccess = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Failed to save preferences: {ex.Message}";
        }
        finally
        {
            _saving = false;
        }
    }
}

