@using sv_f1a8f87ae7e742d4b3071cf5a81b094d.Models

@* Expandable panel for changing the user's password *@

<div class="change-password-panel">
    <button class="btn btn-outline-secondary w-100 text-start" @onclick="TogglePanel">
        <span class="me-2">@(_expanded ? "▾" : "▸")</span>
        Change Password
    </button>

    @if (_expanded)
    {
        <div class="password-fields mt-3">
            <div class="mb-3">
