@using sv_f1a8f87ae7e742d4b3071cf5a81b094d.Models

@* Table of active sessions with revoke confirmation dialog *@

<div class="active-sessions">
    <h5>Active Sessions</h5>

    @if (Sessions is null || Sessions.Count == 0)
    {
        <p class="text-muted">No active sessions.</p>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session.Id != CurrentSessionId)
                                {
                                    <button class="btn btn-sm btn-outline-danger"
                                            @onclick="() => PromptRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="badge bg-success">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }

    @* Revoke confirmation dialog *@
    @if (_sessionToRevoke is not null)
    {
        <div class="modal-backdrop show"></div>
        <div class="modal d-block" tabindex="-1" role="dialog">
            <div class="modal-dialog" role="document">
                <div class="modal-content">
                    <div class="modal-header">
                        <h5 class="modal-title">Revoke Session</h5>
                        <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                    </div>
                    <div class="modal-body">
                        <p>
                            Are you sure you want to revoke the session on
                            <strong>@_sessionToRevoke.Device</strong> from
                            <strong>@_sessionToRevoke.Location</strong>?
                        </p>
                    </div>
                    <div class="modal-footer">
                        <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        <button class="btn btn-danger" @onclick="ConfirmRevoke" disabled="@_revoking">
                            @(_revoking ? "Revoking..." : "Revoke")
                        </button>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public List<ActiveSession> Sessions { get; set; } = new();
    [Parameter] public string? CurrentSessionId { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnRevoke { get; set; }

    private ActiveSession? _sessionToRevoke;
    private bool _revoking;

    private void PromptRevoke(ActiveSession session) => _sessionToRevoke = session;
    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is null) return;

        _revoking = true;
        try
        {
            await OnRevoke.InvokeAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
        }
        finally
        {
            _revoking = false;
        }
    }
}

@using sv_f1a8f87ae7e742d4b3071cf5a81b094d.Models
@using sv_f1a8f87ae7e742d4b3071cf5a81b094d.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h3>Security</h3>

    @if (_loading)
    {
        <p>Loading security settings...</p>
    }
    else
    {
        <ChangePasswordPanel OnChangePassword="HandleChangePassword" />

        <hr />

        <div class="two-factor-section mb-4">
            <h5>Two-Factor Authentication</h5>
            <div class="d-flex align-items-center gap-3">
                <label class="form-check form-switch mb-0">
                    <input type="checkbox" class="form-check-input"
                           checked="@_twoFactorEnabled" disabled />
                    <span class="form-check-label">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </label>
                <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-warning")">
                    @(_twoFactorEnabled ? "✓ Active" : "⚠ Inactive")
                </span>
            </div>
            @if (_lastPasswordChange.HasValue)
            {
                <small class="text-muted d-block mt-2">
                    Last password change: @_lastPasswordChange.Value.ToString("f")
                </small>
            }
        </div>

        <hr />

        <ActiveSessionsTable Sessions="_sessions"
                             CurrentSessionId="@_sessions.FirstOrDefault()?.Id"
                             OnRevoke="HandleRevokeSession" />

        @if (_errorMessage is not null)
        {
            <div class="alert alert-danger mt-3" role="alert">@_errorMessage</div>
        }
    }
</div>

@code {
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = new();
    private bool _loading = true;
    private string? _errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadSettings();
    }

    private async Task LoadSettings()
    {
        _loading = true;
        try
        {
            var settings = await SettingsService.GetSecuritySettingsAsync();
            _twoFactorEnabled = settings.TwoFactorEnabled;
            _lastPasswordChange = settings.LastPasswordChange;
            _sessions = settings.Sessions.ToList();
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task HandleChangePassword((string Current, string New) args)
    {
        _errorMessage = null;
        await SettingsService.ChangePasswordAsync(args.Current, args.New);
        _lastPasswordChange = DateTime.UtcNow;
    }

    private async Task HandleRevokeSession(string sessionId)
    {
        _errorMessage = null;
        try
        {
            await SettingsService.RevokeSessionAsync(sessionId);
            _sessions.RemoveAll(s => s.Id == sessionId);
        }
        catch (Exception ex)
        {
            _errorMessage = $"Failed to revoke session: {ex.Message}";
        }
    }
}

