                            <input type="radio" class="btn-check" name="fontSize"
                                   value="@size"
                                   checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            @size
                        </label>
                    }
                </div>
            </div>

            <div class="mb-4">
                <h5>Language</h5>
                <select class="form-select" style="max-width: 300px;" @bind="_language">
                    @foreach (var lang in _languages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <div class="mb-4">
                <label class="form-check form-switch">
                    <input type="checkbox" class="form-check-input" @bind="_compactMode" />
                    <span class="form-check-label">Compact Mode</span>
                </label>
            </div>

            <hr />

            <h5>Preview</h5>
            <div class="appearance-preview @GetPreviewClasses()">
                <div class="preview-header">Sample Header</div>
                <p class="preview-body">
                    This is a preview of how your content will look with the selected
                    appearance settings. The theme is <strong>@_theme</strong>,
                    font size is <strong>@_fontSize</strong>, and compact mode is
                    <strong>@(_compactMode ? "on" : "off")</strong>.
                </p>
                <div class="preview-actions">
                    <span class="badge bg-primary">Tag</span>
                    <span class="badge bg-secondary">Label</span>
                </div>
            </div>

            <div class="form-actions mt-3">
                <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_saving">
                    @(_saving ? "Saving..." : "Save")
                </button>
            </div>

            @if (_showSuccess)
            {
                <div class="alert alert-success mt-3" role="alert">
                    Appearance settings saved!
                </div>
            }

            @if (_errorMessage is not null)
            {
                <div class="alert alert-danger mt-3" role="alert">
                    @_errorMessage
                </div>
            }
        </div>
    }
</div>

@code {
    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages =
        ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese"];

    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;
    private string? _errorMessage;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        try
        {
            var settings = await SettingsService.GetAppearanceAsync();
            _theme = settings.Theme;
            _fontSize = settings.FontSize;
            _language = settings.Language;
            _compactMode = settings.CompactMode;
        }
        finally
        {
            _loading = false;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{_theme.ToLowerInvariant()}");
        classes.Add($"preview-font-{_fontSize.ToLowerInvariant()}");
        if (_compactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private async Task SaveAppearance()
    {
        _saving = true;
        _showSuccess = false;
        _errorMessage = null;

        try
        {
            var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            _showSuccess = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Failed to save appearance: {ex.Message}";
        }
        finally
        {
            _saving = false;
        }
    }
}

