+    color: #212529;
+    border-color: #dee2e6;
+}
+
+.preview-theme-dark {
+    background: #1e1e2e;
+    color: #e0e0e0;
+    border-color: #444;
+}
+
+.preview-theme-dark .preview-header {
+    color: #ffffff;
+}
+
+.preview-theme-system {
+    background: #f8f9fa;
+    color: #212529;
+    border-color: #adb5bd;
+}
+
+/* Font size variants */
+.preview-font-small {
+    font-size: 0.85rem;
+}
+
+.preview-font-small .preview-header {
+    font-size: 0.95rem;
+}
+
+.preview-font-medium {
+    font-size: 1rem;
+}
+
+.preview-font-large {
+    font-size: 1.15rem;
+}
+
+.preview-font-large .preview-header {
+    font-size: 1.3rem;
+}
+
+/* Compact mode */
+.preview-compact {
+    padding: 0.75rem;
+    line-height: 1.3;
+}
+
+.preview-compact .preview-body {
+    margin-bottom: 0.4rem;
+}
+
+/* Modal overrides for session revoke dialog */
+::deep .modal-backdrop {
+    position: fixed;
+    top: 0;
+    left: 0;
+    width: 100vw;
+    height: 100vh;
+    z-index: 1040;
+}
+
+::deep .modal.d-block {
+    position: fixed;
+    top: 0;
+    left: 0;
+    width: 100vw;
+    height: 100vh;
+    z-index: 1050;
+    display: flex !important;
+    align-items: center;
+    justify-content: center;
+}
